import React, { useState } from "react";
import Carousel from "@brainhubeu/react-carousel";
import "@brainhubeu/react-carousel/lib/style.css";
import slidesData from "./SlidesData";
import "./SliderData.css";

const SliderData = () => {
  const [selectedImage, setSelectedImage] = useState(null);
  const [hoveredText, setHoveredText] = useState("");

  return (
    <div className="carousel-container" id="slider">
      <div className="carousel-title">
        <h2>My Projects</h2>
      </div>

      <Carousel
        arrows
        slidesPerPage={3}
        infinite
        animationSpeed={200}
        centered
        offset={50}
        itemWidth={400}
        breakpoints={{
          960: { slidesPerPage: 1, arrows: false, itemWidth: 250 },
        }}
      >
        {slidesData.map((slide, index) => (
          <div
            key={index}
            className="carousel-item"
            onClick={() => setSelectedImage(slide.src)}
            onMouseEnter={() => setHoveredText(slide.desc)}
            onMouseLeave={() => setHoveredText("")}
          >
            <img src={slide.src} alt={slide.alt} className="carousel-image" />
            {hoveredText && (
              <div className="tooltip">{hoveredText}</div>
            )}
          </div>
        ))}
      </Carousel>

      {selectedImage && (
        <div className="modal" onClick={() => setSelectedImage(null)}>
          <img src={selectedImage} alt="Expanded" className="modal-image" />
        </div>
      )}
    </div>
  );
};

export default SliderData;

